CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'student',is_active INTEGER NOT NULL DEFAULT 1,auth_version INTEGER NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CHECK(role IN ('student','instructor','admin'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS courses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,instructor_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,cover_key VARCHAR(20) NOT NULL DEFAULT 'default',status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(instructor_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,CHECK(status IN ('draft','published','archived')),INDEX idx_courses_status_created(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS chapters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,CHECK(position>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lessons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,chapter_id BIGINT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,youtube_video_id VARCHAR(11) NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(chapter_id) REFERENCES chapters(id) ON DELETE CASCADE,CHECK(position>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS enrollments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,course_id BIGINT UNSIGNED NOT NULL,last_lesson_id BIGINT UNSIGNED NULL,completed_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,course_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE RESTRICT,FOREIGN KEY(last_lesson_id) REFERENCES lessons(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS lesson_progress (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,lesson_id BIGINT UNSIGNED NOT NULL,completed_at DATETIME NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,lesson_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS quizzes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quiz_id BIGINT UNSIGNED NOT NULL,prompt VARCHAR(500) NOT NULL,explanation TEXT NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS answers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL,text VARCHAR(250) NOT NULL,is_correct INTEGER NOT NULL,position INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS quiz_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,quiz_id BIGINT UNSIGNED NOT NULL,request_id VARCHAR(36) NOT NULL,submission_hash CHAR(64) NOT NULL,correct_count INTEGER NOT NULL,total_questions INTEGER NOT NULL,score_percent DECIMAL(5,2) NOT NULL,passed INTEGER NOT NULL,submitted_at DATETIME NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(user_id,request_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE RESTRICT,INDEX idx_attempt_user_quiz(user_id,quiz_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS quiz_answers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,answer_id BIGINT UNSIGNED NULL,is_correct INTEGER NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE(attempt_id,question_id),FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(id) ON DELETE RESTRICT,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE RESTRICT,FOREIGN KEY(answer_id) REFERENCES answers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
